insert into public.quiz_quizzes (id, label, title, subtitle, mode, position) values
  ('q1', 'Quiz 1', 'Énergie, notions fondamentales', '10 questions générales : cycles combinés, turbines à gaz, ISO 50001, pinch, LCOE, PCS/PCI, émissions.', 'entrainement', 1),
  ('q2', 'Quiz 2', 'Exploitation d’une centrale à cycle combiné gaz', '10 questions ciblées : turbine à gaz, chaudière de récupération, aérocondenseur, chimie de l’eau, consignation, protections.', 'entrainement', 2),
  ('q3', 'Quiz 3', 'Suite, exploitation, performance et réseau', '10 questions : réglage de fréquence, black start, EOH, vibrations, heat rate, lavage compresseur, ballon HRSG, ISO 50001, facteur de charge.', 'entrainement', 3),
  ('q4', 'Quiz 4', 'Série 3, chimie eau-vapeur, protections et performance', '10 questions pointues : conductivité cationique, silice, dégazage, protections, ASME PTC 46, calcul de débit de gaz, contre-pression, indice de Wobbe.', 'entrainement', 4),
  ('examen', 'Examen', 'Quatre niveaux de difficulté croissante', 'Quatre niveaux : Fondamental (Q1-5), Intermédiaire (Q6-10), Avancé (Q11-13), Expert (Q14-15). Barème conseillé : 1 point par bonne réponse, total sur 15.', 'examen', 5)
insert into public.quiz_questions (id, quiz_id, position, level, prompt, choices, answer, explanation, calc) values
  ('q1-01', 'q1', 1, null, 'Quel est l’ordre de grandeur du rendement électrique (base PCI) d’un cycle combiné gaz moderne de grande taille ?', '["35 à 40 %","45 à 50 %","55 à 62 %","70 à 75 %"]'::jsonb, 'C', 'Les CCGT récents de classe F/H/J atteignent 55 à 62 % de rendement net, grâce à la récupération de la chaleur d’échappement de la turbine à gaz dans un cycle vapeur. Les turbines à gaz en cycle simple se situent plutôt entre 35 et 42 %.', false),
  ('q1-02', 'q1', 2, null, 'Quand la température ambiante augmente, que devient la puissance maximale d’une turbine à gaz ?', '["Elle augmente, car l’air est plus chaud et plus énergétique","Elle diminue, car l’air est moins dense et le débit massique chute","Elle reste constante grâce à la régulation","Elle augmente uniquement à charge partielle"]'::jsonb, 'B', 'Un air plus chaud est moins dense : le débit massique aspiré par le compresseur baisse, tout comme le taux de compression effectif. La puissance chute typiquement de 0,5 à 0,9 % par °C. C’est la raison d’être des systèmes de refroidissement de l’air d’admission (fogging, évaporatif).', false),
  ('q1-03', 'q1', 3, null, 'Quel concept est propre à la norme ISO 50001 par rapport à une norme de management générique comme l’ISO 9001 ?', '["La revue de direction","L’amélioration continue (PDCA)","La situation de référence énergétique et les indicateurs de performance énergétique (IPE)","L’audit interne"]'::jsonb, 'C', 'L’ISO 50001 impose d’établir une situation de référence énergétique (SRE) et des IPE normalisés par les variables pertinentes (charge, météo, production) pour démontrer l’amélioration de la performance énergétique. Les autres éléments sont communs à toutes les normes de système de management.', false),
  ('q1-04', 'q1', 4, null, 'En analyse pinch (intégration énergétique), que signifie la règle du point de pincement ?', '["Il ne faut pas transférer de chaleur à travers le pincement, ni utiliser d’utilité froide au-dessus ni d’utilité chaude en dessous","Il faut maximiser l’utilité chaude au-dessus du pincement","L’écart de température minimal doit être nul au pincement","Le pincement est le point où la pression est minimale dans le réseau"]'::jsonb, 'A', 'Le pincement sépare le procédé en deux zones : au-dessus, un puits de chaleur (besoin d’utilité chaude seule) ; en dessous, une source de chaleur (utilité froide seule). Transférer de la chaleur à travers le pincement augmente à la fois les besoins en chaud et en froid.', false),
  ('q1-05', 'q1', 5, null, 'Un alternateur de 100 MVA fonctionne à cos φ = 0,8 et à sa puissance apparente nominale. Quelle puissance active délivre-t-il ?', '["60 MW","80 MW","100 MW","125 MW"]'::jsonb, 'B', 'P = S × cos φ = 100 × 0,8 = 80 MW. La puissance réactive associée est Q = S × sin φ = 60 Mvar.', true),
  ('q1-06', 'q1', 6, null, 'Comment se définit le LCOE (coût actualisé de l’énergie) ?', '["Le coût d’investissement divisé par la puissance installée","La somme des coûts actualisés sur la durée de vie divisée par la somme de l’énergie produite actualisée","Le prix moyen de vente de l’électricité sur le marché de gros","Le coût du combustible divisé par le rendement"]'::jsonb, 'B', 'LCOE = Σ (investissement + exploitation + combustible + démantèlement) actualisés / Σ MWh produits actualisés. Il permet de comparer des filières aux profils de coûts très différents, mais ne reflète pas les coûts système (intermittence, réseau).', false),
  ('q1-07', 'q1', 7, null, 'Dans le cycle vapeur d’une centrale, que provoque une baisse de la pression de condensation (meilleur vide au condenseur) ?', '["Une baisse du rendement du cycle","Une augmentation du rendement, car la température moyenne de rejet de chaleur diminue","Aucun effet sur le rendement","Une augmentation du titre en vapeur en sortie de turbine, sans gain de puissance"]'::jsonb, 'B', 'Selon Carnot et Rankine, abaisser la température de la source froide augmente le travail récupérable : la détente va plus loin dans la turbine. Le gain est limité par la température de la source froide (air ou eau) et par l’humidité en fin de détente. C’est pourquoi l’encrassement d’un condenseur ou d’un aérocondenseur fait perdre de la puissance.', false),
  ('q1-08', 'q1', 8, null, 'Quel principe permet aux chambres de combustion DLN (Dry Low NOx) de réduire les NOx sans injection d’eau ou de vapeur ?', '["Une combustion prémélangée pauvre qui abaisse la température de flamme","Une combustion avec excès d’air minimal pour limiter l’oxygène","Un catalyseur placé dans la chaudière de récupération uniquement","Un préchauffage du gaz à très haute température"]'::jsonb, 'A', 'Les NOx thermiques croissent exponentiellement avec la température de flamme. Le prémélange air-gaz pauvre homogénéise le mélange et évite les zones chaudes stœchiométriques. En contrepartie, la plage de stabilité est étroite (risques de pulsations et de CO à faible charge).', false),
  ('q1-09', 'q1', 9, null, 'Pourquoi le PCS d’un gaz naturel est-il supérieur à son PCI (d’environ 10 %) ?', '["Le PCS inclut l’énergie des impuretés du gaz","Le PCS tient compte de la chaleur latente de condensation de la vapeur d’eau produite par la combustion","Le PCI est mesuré à pression plus élevée","Le PCS inclut le travail de compression du gaz"]'::jsonb, 'B', 'La combustion de l’hydrogène du combustible produit de la vapeur d’eau. Le PCS compte la chaleur récupérée si cette vapeur est condensée ; le PCI suppose qu’elle reste à l’état vapeur. Pour le gaz naturel, PCS ≈ 1,11 × PCI. Il faut toujours préciser la base utilisée pour un rendement.', false),
  ('q1-10', 'q1', 10, null, 'Quel est l’ordre de grandeur du facteur d’émission du gaz naturel brûlé (CO₂ direct), par kWh PCI de combustible ?', '["0,05 kg CO₂/kWh","0,20 kg CO₂/kWh","0,35 kg CO₂/kWh","0,50 kg CO₂/kWh"]'::jsonb, 'B', 'Environ 56 kg CO₂/GJ PCI, soit près de 0,20 kg CO₂ par kWh PCI de combustible. Divisé par un rendement de 55 à 60 %, cela donne environ 0,33 à 0,37 kg CO₂ par kWh électrique pour un CCGT.', false),
  ('q2-01', 'q2', 1, null, 'Sur une turbine à gaz, un écart de température d’échappement (exhaust spread) qui augmente révèle le plus souvent :', '["Une baisse de la température ambiante","Une combustion non uniforme (injecteur ou brûleur encrassé ou défaillant) ou un thermocouple défaillant","Un excès de pression dans la chaudière de récupération","Un défaut de l’alternateur"]'::jsonb, 'B', 'Les thermocouples d’échappement sont répartis sur la circonférence : un écart important entre eux traduit une répartition inégale de la combustion entre les chambres, ou une mesure défaillante. Il faut distinguer les deux avant de décider d’une inspection des injecteurs.', false),
  ('q2-02', 'q2', 2, null, 'Quelle est la conséquence principale de l’encrassement des filtres du caisson d’aspiration d’une turbine à gaz ?', '["Une hausse de la puissance par réduction de la température d’entrée","Aucune conséquence tant que le filtre n’est pas colmaté","Une baisse de la température d’échappement uniquement","Une perte de charge accrue qui réduit le débit d’air, donc la puissance, et dégrade le rendement"]'::jsonb, 'D', 'Une perte de charge à l’aspiration diminue la pression d’entrée du compresseur, donc le débit massique et le taux de compression. La puissance baisse et le heat rate se dégrade. Le suivi de la perte de charge (ΔP) est le bon indicateur pour une maintenance prédictive.', false),
  ('q2-03', 'q2', 3, null, 'Dans une chaudière de récupération (HRSG), que désigne le « pincement » (pinch point) de l’évaporateur ?', '["L’écart entre la température des gaz en sortie d’évaporateur et la température de saturation de l’eau","L’écart entre la température d’entrée et de sortie de l’eau d’alimentation","La pression minimale du ballon","La température maximale admissible des tubes du surchauffeur"]'::jsonb, 'A', 'Plus le pincement est faible, plus la récupération de chaleur est poussée et plus la production de vapeur est élevée, mais la surface d’échange nécessaire augmente. Un pincement qui se dégrade en exploitation peut traduire un encrassement côté gaz.', false),
  ('q2-04', 'q2', 4, null, 'Quelle température ambiante conditionne en premier lieu les performances d’un aérocondenseur ?', '["La température de bulbe humide","La température du point de rosée","La température de bulbe sec de l’air","La température du sol"]'::jsonb, 'C', 'L’aérocondenseur échange de la chaleur sensible avec l’air, sans évaporation d’eau. Sa limite est donc la température de bulbe sec, contrairement à une tour de refroidissement humide qui dépend du bulbe humide. Par temps chaud, ou avec des faisceaux encrassés, la pression d’échappement de la turbine à vapeur monte et la puissance baisse.', false),
  ('q2-05', 'q2', 5, null, 'Quel est l’ordre de grandeur de la conductivité d’une eau déminée de bonne qualité en sortie de lit mixte ?', '["Inférieure ou égale à 0,1 µS/cm","Environ 5 µS/cm","Environ 50 µS/cm","Environ 500 µS/cm"]'::jsonb, 'A', 'L’eau pure théorique est à environ 0,055 µS/cm à 25 °C. Une eau déminée de bonne qualité reste en dessous de 0,1 µS/cm. Au stockage, l’absorption de CO₂ de l’air et les contaminations font monter la conductivité, d’où l’intérêt des matelas d’azote ou de filtres à CO₂ sur les évents.', false),
  ('q2-06', 'q2', 6, null, 'Qu’est-ce que la corrosion assistée par l’écoulement (FAC) dans un circuit eau-vapeur ?', '["Une fissuration due aux chlorures sous contrainte","Un dépôt de silice sur les ailettes de la turbine à vapeur","Une corrosion provoquée par un contact galvanique entre deux métaux","La dissolution de la couche protectrice de magnétite sous l’effet de l’écoulement, favorisée par un pH bas et un milieu réducteur"]'::jsonb, 'D', 'La FAC amincit progressivement les tubes en acier au carbone (économiseurs, évaporateurs basse pression, coudes). Elle se maîtrise par un pH d’eau d’alimentation adapté, un traitement oxygéné ou un choix de matériaux plus résistants.', false),
  ('q2-07', 'q2', 7, null, 'Quelle séquence correspond à la logique d’une consignation électrique ?', '["Vérifier l’absence de tension, puis séparer, puis condamner","Séparer, condamner, identifier puis vérifier l’absence de tension, mettre à la terre et en court-circuit","Condamner, puis commencer le travail, puis séparer","Mettre à la terre, puis séparer, puis vérifier l’absence de tension"]'::jsonb, 'B', 'On sépare l’installation de toute source, on condamne la séparation (cadenas, étiquette), on identifie l’ouvrage, puis on vérifie l’absence de tension (VAT) avant de mettre à la terre et en court-circuit. La VAT n’a de sens qu’une fois la séparation faite, et la mise à la terre vient après la VAT.', false),
  ('q2-08', 'q2', 8, null, 'Pourquoi réalise-t-on un cycle de purge avant l’allumage d’une turbine à gaz ?', '["Pour préchauffer le rotor","Pour refroidir l’huile de graissage","Pour étalonner les thermocouples","Pour évacuer tout mélange combustible résiduel du circuit des gaz et éviter une explosion à l’allumage"]'::jsonb, 'D', 'La turbine est lancée par le dispositif de démarrage pour balayer plusieurs volumes de la ligne d’échappement et de la chaudière de récupération. Cela évacue le gaz non brûlé éventuel avant que l’allumage ne soit autorisé.', false),
  ('q2-09', 'q2', 9, null, 'Pourquoi limite-t-on les gradients de montée en température lors du démarrage d’une turbine à vapeur ?', '["Pour limiter les contraintes thermiques et la fatigue oligocyclique du rotor et du corps","Pour augmenter la production de condensats","Pour réduire la consommation d’eau déminée","Pour éviter la corrosion de l’alternateur"]'::jsonb, 'A', 'Un rotor massif chauffé trop vite présente un fort écart de température entre la surface et le cœur, donc des contraintes élevées. Les démarrages (surtout à froid) consomment de la durée de vie par fatigue. C’est pourquoi on suit la contrainte rotor et on respecte des courbes de montée en charge.', false),
  ('q2-10', 'q2', 10, null, 'Que détecte la protection de terre restreinte (REF) d’un transformateur ?', '["Les surcharges thermiques de l’huile","Les défauts à la terre à l’intérieur de la zone de l’enroulement protégé, par comparaison du courant de neutre et de la somme des courants de phase","Les défauts entre spires uniquement","Les surtensions atmosphériques sur le réseau"]'::jsonb, 'B', 'La REF est une protection différentielle limitée à un enroulement, très sensible aux défauts à la terre proches du neutre, que la différentielle générale peut détecter trop faiblement. Elle est souvent complétée par la protection différentielle du transformateur et les protections mécaniques (Buchholz, température).', false),
  ('q3-01', 'q3', 1, null, 'Un groupe a un statisme (droop) de 5 % sur un réseau à 50 Hz. Que signifie cette valeur ?', '["Une variation de fréquence de 5 Hz fait varier la puissance de 5 %","Une variation de fréquence de 2,5 Hz fait varier la puissance de 100 % de la puissance nominale","Le groupe perd 5 % de rendement à charge partielle","La tension peut varier de 5 % sans déclenchement"]'::jsonb, 'B', 'Un statisme de 5 % signifie qu’un écart de fréquence de 5 % (2,5 Hz à 50 Hz) fait passer la puissance de 0 à 100 %. C’est la base du réglage primaire de fréquence : plusieurs groupes se partagent la variation de charge proportionnellement à leur puissance.', true),
  ('q3-02', 'q3', 2, null, 'Qu’est-ce qu’un démarrage en black start ?', '["Un démarrage de nuit pour limiter les pertes thermiques","Un démarrage après maintenance, sans mise en parallèle","Un démarrage forcé après un déclenchement sur défaut","Un démarrage sans alimentation externe du réseau, grâce à une source autonome (diesel, groupe dédié), pour reconstituer le réseau après un blackout"]'::jsonb, 'D', 'Après un effondrement du réseau, la centrale ne peut plus compter sur le soutirage externe pour ses auxiliaires. Un groupe de secours alimente les auxiliaires du premier groupe, qui peut alors réalimenter le réseau pas à pas.', false),
  ('q3-03', 'q3', 3, null, 'Pourquoi les inspections d’une turbine à gaz (combustion, parcours des gaz chauds, majeure) se planifient-elles en heures équivalentes d’exploitation (EOH) plutôt qu’en heures réelles ?', '["Parce que les démarrages, déclenchements, charges élevées et combustibles différents usent les pièces chaudes plus vite que les heures à charge stable","Parce que les heures réelles ne peuvent pas être comptées","Parce que l’EOH est imposé par la réglementation environnementale","Parce que l’EOH ne tient compte que des heures de nuit"]'::jsonb, 'A', 'Un démarrage ou un déclenchement sur défaut peut compter pour plusieurs dizaines d’heures équivalentes, car la fatigue thermique des pièces chaudes est bien supérieure à celle d’un fonctionnement stable. Le constructeur fournit des facteurs de pondération pour chaque événement.', false),
  ('q3-04', 'q3', 4, null, 'Sur un arbre de turbomachine, une composante de vibration dominante à 1× la vitesse de rotation évoque en premier lieu :', '["Un défaut de roulement à billes","Une dent d’engrenage cassée","Un balourd (déséquilibre du rotor)","Une cavitation"]'::jsonb, 'C', 'Le balourd produit une force centrifuge tournant avec le rotor, donc une vibration synchrone à 1×. Un désalignement donne plutôt du 2× et de l’axial ; les défauts de roulement apparaissent à des fréquences non synchrones.', false),
  ('q3-05', 'q3', 5, null, 'Un cycle combiné affiche un heat rate net de 6 000 kJ/kWh (base PCI). Quel est son rendement net ?', '["50 %","55 %","60 %","65 %"]'::jsonb, 'C', 'Rendement = 3 600 kJ/kWh ÷ heat rate = 3 600 ÷ 6 000 = 0,60, soit 60 %. 3 600 kJ est l’équivalent énergétique d’un kWh.', true),
  ('q3-06', 'q3', 6, null, 'Que permet (et ne permet pas) un lavage du compresseur d’une turbine à gaz ?', '["Il récupère la dégradation due à l’encrassement, mais pas celle due à l’érosion ou à l’usure des aubes","Il récupère toute la dégradation de performance","Il ne récupère que la dégradation de la turbine, pas celle du compresseur","Il ne sert qu’à refroidir le compresseur"]'::jsonb, 'A', 'Le lavage (en ligne ou hors ligne) élimine les dépôts sur les aubes et rétablit le débit et le rendement du compresseur. La dégradation non récupérable (érosion, jeux, corrosion) ne se corrige qu’en révision.', false),
  ('q3-07', 'q3', 7, null, 'Pourquoi utilise-t-on une régulation de niveau à trois éléments sur le ballon d’une chaudière de récupération ?', '["Pour mesurer la conductivité de l’eau","Pour compenser les phénomènes de gonflement et de retrait (swell/shrink) en combinant niveau, débit de vapeur et débit d’eau d’alimentation","Pour réguler la température de la vapeur surchauffée","Pour équilibrer la pression entre trois ballons"]'::jsonb, 'B', 'Lors d’un appel de vapeur, la pression chute et les bulles de vapeur gonflent le mélange : le niveau mesuré monte alors que la masse d’eau diminue. La mesure du débit de vapeur permet d’anticiper et d’éviter une mauvaise réaction du régulateur, source de déclenchement sur niveau haut ou bas.', false),
  ('q3-08', 'q3', 8, null, 'Pourquoi impose-t-on une température minimale de l’eau à l’entrée du préchauffeur de condensat d’une chaudière de récupération ?', '["Pour augmenter la pression du dégazeur","Pour augmenter le débit de vapeur HP","Pour éviter que les gaz d’échappement condensent sur les tubes froids, ce qui provoque une corrosion acide","Pour protéger la pompe d’extraction contre la cavitation"]'::jsonb, 'C', 'Si la paroi des tubes passe sous le point de rosée de l’eau (ou des acides) des gaz, de l’eau acide se condense et corrode les tubes et les ailettes. On maintient donc l’eau au-dessus d’un seuil, souvent par recirculation du condensat chaud.', false),
  ('q3-09', 'q3', 9, null, 'Dans l’ISO 50001, qu’appelle-t-on un usage énergétique significatif (UES) ?', '["Tout équipement raccordé au réseau électrique","Un usage qui n’est pas mesurable","Un usage dont le coût est supérieur à celui du combustible","Un usage qui représente une consommation d’énergie substantielle ou un potentiel d’amélioration considérable de la performance énergétique"]'::jsonb, 'D', 'L’organisme identifie ses UES par l’analyse énergétique (consommations, usages, facteurs influents), puis les pilote avec des IPE et des plans d’action. Dans une centrale, les auxiliaires (pompes, ventilateurs de l’aérocondenseur, compresseurs de gaz) en sont des candidats typiques.', false),
  ('q3-10', 'q3', 10, null, 'Une centrale de 400 MW produit 2 400 GWh sur une année de 8 760 heures. Quel est son facteur de charge ?', '["Environ 48 %","Environ 58 %","Environ 68 %","Environ 78 %"]'::jsonb, 'C', 'Facteur de charge = énergie produite ÷ (puissance nominale × heures) = 2 400 ÷ (0,4 × 8 760) = 2 400 ÷ 3 504 ≈ 0,685, soit environ 68 %.', true),
  ('q4-01', 'q4', 1, null, 'Que mesure la conductivité cationique (après échangeur cationique) dans un circuit eau-vapeur ?', '["La conductivité de l’eau brute avant déminéralisation","La contamination par des anions (chlorures, sulfates, CO₂, acides organiques), en supprimant l’effet masquant de l’ammoniaque ou de l’amine de conditionnement","Uniquement le pH de l’eau d’alimentation","La teneur en oxygène dissous"]'::jsonb, 'B', 'La conductivité cationique est mesurée après passage sur résine cationique : l’ammoniaque ou l’amine de conditionnement est éliminée (elle masque le signal) et il reste les acides correspondant aux anions présents (chlorures, sulfates, CO₂, acétate, formiate). C’est l’indicateur de référence de la contamination du circuit eau-vapeur ; les valeurs d’alerte se situent couramment autour de 0,2 µS/cm.', false),
  ('q4-02', 'q4', 2, null, 'Pourquoi surveille-t-on la silice dans l’eau du ballon HP et dans la vapeur ?', '["Parce qu’elle fait monter le pH de l’eau de chaudière","Parce qu’elle attaque directement les roulements de l’alternateur","Parce qu’elle est entraînée par la vapeur (volatilité croissante avec la pression) et se dépose sur les aubes de la turbine lors de la détente","Parce qu’elle augmente la conductivité spécifique de la vapeur"]'::jsonb, 'C', 'La silice est volatile dans la vapeur surchauffée, d’autant plus que la pression est élevée. Lors de la détente dans la turbine, sa solubilité chute et elle se dépose sur les aubes (surtout en MP/BP), ce qui dégrade le rendement et la puissance. D’où le contrôle de la silice en eau de chaudière et en vapeur.', false),
  ('q4-03', 'q4', 3, null, 'Quel est le principe physique du dégazage thermique de l’eau d’alimentation ?', '["La solubilité des gaz dissous tend vers zéro à la température de saturation, et la vapeur de balayage les évacue","Une résine échangeuse d’ions piège l’oxygène","Une membrane filtre l’oxygène par osmose","L’augmentation de la pression dissout les gaz dans l’eau"]'::jsonb, 'A', 'La solubilité des gaz dans l’eau diminue avec la température et tend vers zéro à l’ébullition (loi de Henry). Le dégazeur thermique chauffe l’eau à saturation et un balayage de vapeur évacue O₂ et CO₂ libérés.', false),
  ('q4-04', 'q4', 4, null, 'Comment une protection différentielle de transformateur évite-t-elle de déclencher à tort lors de l’enclenchement (courant d’inrush) ?', '["Une retenue par harmonique de rang 5","Une temporisation de 10 secondes","Une retenue par la tension homopolaire","Une retenue par harmonique de rang 2"]'::jsonb, 'D', 'L’enclenchement d’un transformateur provoque un courant magnétisant très élevé mais un seul côté voit le courant : la différentielle y verrait un faux défaut. Ce courant est riche en harmonique 2, qui sert de retenue. L’harmonique 5 sert plutôt à détecter la surexcitation.', false),
  ('q4-05', 'q4', 5, null, 'Quel phénomène la protection contre la perte d’excitation (ANSI 40) d’un alternateur cherche-t-elle à détecter et à limiter ?', '["Une surtension du réseau","L’alternateur absorbe de la puissance réactive du réseau et peut passer en fonctionnement asynchrone, avec échauffement du rotor et du stator","Un défaut d’isolement du bobinage statorique uniquement","Une survitesse de la turbine"]'::jsonb, 'B', 'Sans excitation, l’alternateur perd le synchronisme et fonctionne en générateur asynchrone en absorbant de la puissance réactive du réseau. Cela provoque des courants induits dans le rotor et un surcourant statorique, donc des échauffements. La protection (code ANSI 40) détecte généralement une impédance vue des bornes qui entre dans une caractéristique mho côté capacitif.', false),
  ('q4-06', 'q4', 6, null, 'Pourquoi la protection terre stator à 100 % d’un alternateur utilise-t-elle l’harmonique 3 ?', '["Pour détecter les défauts entre phases","Pour mesurer la fréquence du réseau","Pour couvrir la zone proche du neutre, où la tension fondamentale d’un défaut à la terre est trop faible pour être détectée","Pour déclencher plus vite en cas de survitesse"]'::jsonb, 'C', 'La protection terre stator à minimum de tension homopolaire (59N) couvre environ 90 à 95 % de l’enroulement. Près du neutre, la tension fondamentale d’un défaut est trop faible. La mesure de l’harmonique 3 (ou l’injection de signal) permet d’atteindre les derniers pourcents du bobinage : c’est la protection terre stator à 100 %.', false),
  ('q4-07', 'q4', 7, null, 'Quel code d’essai ASME couvre la performance globale d’une centrale à cycle combiné ?', '["ASME PTC 6","ASME PTC 22","ASME PTC 46","ASME PTC 4.4"]'::jsonb, 'C', 'L’ASME PTC 46 couvre la performance globale d’une centrale (puissance, heat rate) et les corrections aux conditions de référence. PTC 22 concerne les turbines à gaz, PTC 6 les turbines à vapeur, PTC 4.4 les chaudières de récupération.', false),
  ('q4-08', 'q4', 8, null, 'Une centrale délivre 400 MW nets à un heat rate de 6 200 kJ/kWh (PCI). Avec un gaz de PCI 36 MJ/Nm³, quel est le débit de gaz consommé ?', '["Environ 34 400 Nm³/h","Environ 68 900 Nm³/h","Environ 103 300 Nm³/h","Environ 138 000 Nm³/h"]'::jsonb, 'B', 'Énergie combustible = 400 000 kW × 6 200 kJ/kWh = 2,48 × 10⁹ kJ/h = 2 480 000 MJ/h. Divisée par 36 MJ/Nm³, cela donne environ 68 900 Nm³/h.', true),
  ('q4-09', 'q4', 9, null, 'Quel est l’effet d’un encrassement côté gaz des faisceaux de la chaudière de récupération sur la turbine à gaz ?', '["Elle augmente la contre-pression à l’échappement de la turbine à gaz et réduit sa puissance et son rendement","Elle augmente la puissance de la turbine à gaz en augmentant la température de sortie","Elle n’agit que sur la turbine à vapeur","Elle réduit la consommation de gaz"]'::jsonb, 'A', 'La contre-pression à l’échappement réduit le rapport de détente de la turbine à gaz, donc sa puissance et son rendement, et les pertes de charge dans la chaudière s’ajoutent à celles du conduit. Elle peut aussi élever la température d’échappement. Un ΔP gaz qui dérive est un bon signal de maintenance.', false),
  ('q4-10', 'q4', 10, null, 'Qu’est-ce que l’indice de Wobbe et pourquoi est-il critique pour une turbine à gaz DLN ?', '["Le rapport PCI/PCS, qui décrit la quantité d’eau dans le gaz","La teneur en soufre, qui détermine la corrosion","La température de rosée du gaz","Le rapport PCS/√(densité relative), qui mesure l’interchangeabilité des gaz : une variation trop forte déstabilise la flamme d’une chambre DLN"]'::jsonb, 'D', 'L’indice de Wobbe vaut PCS/√d (d = densité relative par rapport à l’air). Deux gaz de même Wobbe donnent la même puissance pour une même perte de charge d’injecteur. Les chambres DLN, réglées en prémélange pauvre, tolèrent une plage étroite (souvent de l’ordre de ±5 %) avant instabilités de flamme, pulsations ou hausse des émissions.', false),
  ('examen-01', 'examen', 1, 1, 'Quelle énergie produit une centrale de 250 MW fonctionnant à pleine puissance pendant 6 heures ?', '["42 MWh","256 MWh","1 500 MWh","15 000 MWh"]'::jsonb, 'C', 'Énergie = puissance × durée = 250 MW × 6 h = 1 500 MWh.', true),
  ('examen-02', 'examen', 2, 1, 'Quel cycle thermodynamique modélise une turbine à gaz ?', '["Rankine","Brayton","Stirling","Otto"]'::jsonb, 'B', 'Le cycle de Brayton (compression, combustion à pression constante, détente) décrit la turbine à gaz. Le cycle de Rankine décrit le cycle vapeur.', false),
  ('examen-03', 'examen', 3, 1, 'Quel est le constituant principal du gaz naturel ?', '["Le propane","L’hydrogène","Le butane","Le méthane"]'::jsonb, 'D', 'Le gaz naturel est composé à plus de 80 à 95 % de méthane (CH₄), avec de l’éthane, du propane, de l’azote et du CO₂ en quantités variables.', false),
  ('examen-04', 'examen', 4, 1, 'Quelle expression donne la puissance active d’un système triphasé équilibré (U tension composée, I courant de ligne) ?', '["P = √3 × U × I × cos φ","P = U × I × sin φ","P = 3 × U × I","P = U / I × cos φ"]'::jsonb, 'A', 'En triphasé équilibré, P = √3 × U (tension composée) × I × cos φ.', false),
  ('examen-05', 'examen', 5, 1, 'Quelle est la formule du rendement de Carnot ?', '["1 − T_chaud/T_froid, en °C","T_froid/T_chaud, en °C","1 − T_froid/T_chaud, en kelvins","T_chaud − T_froid, en kelvins"]'::jsonb, 'C', 'η Carnot = 1 − T_froid/T_chaud avec des températures absolues en kelvins. C’est le rendement maximal théorique d’une machine entre deux sources.', false),
  ('examen-06', 'examen', 6, 2, 'Pourquoi les gaz d’échappement d’une turbine à gaz contiennent-ils encore environ 12 à 15 % d’oxygène ?', '["Parce que le combustible contient de l’oxygène","Parce que l’excès d’air sert à limiter la température des gaz admissible par les matériaux de la turbine","Parce que l’oxygène n’est pas consommé par la combustion","Parce que le compresseur ajoute de l’oxygène"]'::jsonb, 'B', 'La température des gaz de combustion est limitée par la tenue des matériaux de la turbine. On travaille donc avec un fort excès d’air (λ ≈ 2 à 3), ce qui laisse typiquement 12 à 15 % d’oxygène dans les gaz d’échappement.', false),
  ('examen-07', 'examen', 7, 2, 'Un alternateur est couplé à un réseau puissant. Que provoque une augmentation du courant d’excitation, à puissance active constante ?', '["La fréquence du réseau augmente","La puissance active augmente","La vitesse de la turbine augmente","La puissance réactive fournie au réseau augmente, la puissance active restant inchangée"]'::jsonb, 'D', 'Sur un réseau puissant, la puissance active est fixée par la turbine, tandis que l’excitation règle la puissance réactive. Une surexcitation fait fournir de la puissance réactive au réseau, une sous-excitation en fait absorber.', false),
  ('examen-08', 'examen', 8, 2, 'Un ventilateur piloté par variateur passe de 100 % à 80 % de sa vitesse. Quelle est approximativement la puissance absorbée (par rapport à la puissance nominale) ?', '["80 %","64 %","51 %","40 %"]'::jsonb, 'C', 'Selon les lois de similitude des ventilateurs, la puissance varie comme le cube de la vitesse : 0,8³ = 0,512, soit environ 51 % de la puissance nominale. Le débit, lui, baisse proportionnellement à la vitesse (80 %).', true),
  ('examen-09', 'examen', 9, 2, 'Pourquoi réchauffe-t-on le gaz naturel avant (ou pendant) sa détente dans un poste de détente ?', '["Pour compenser le refroidissement dû à la détente (Joule-Thomson) et éviter hydrates et givre","Pour augmenter la pression en aval","Pour augmenter l’indice de Wobbe","Pour faire monter le PCS du gaz"]'::jsonb, 'A', 'La détente du gaz (effet Joule-Thomson) abaisse sa température d’environ 0,4 à 0,5 °C par bar. Sans réchauffage, la température peut passer sous 0 °C et former des hydrates ou du givre, et abaisser la température du gaz en dessous des valeurs admises par la turbine.', false),
  ('examen-10', 'examen', 10, 2, 'Pourquoi limite-t-on le taux d’humidité de la vapeur dans les derniers étages d’une turbine à vapeur ?', '["Pour augmenter la production de vapeur","Pour limiter l’érosion des aubes des derniers étages par les gouttelettes d’eau","Pour réduire la consommation d’eau","Pour augmenter la pression au condenseur"]'::jsonb, 'B', 'Des gouttelettes d’eau accélérées frappent les aubes des derniers étages et les érodent. C’est pourquoi on limite le taux d’humidité en fin de détente (titre généralement supérieur à environ 0,88–0,9), ce qui borne la pression minimale au condenseur pour un cycle donné.', false),
  ('examen-11', 'examen', 11, 3, 'Une turbine à gaz a un rendement de 38 %. Sa chaudière de récupération récupère 85 % de la chaleur des gaz d’échappement et le cycle vapeur a un rendement de 35 %. En négligeant les autres pertes, quel est le rendement du cycle combiné ?', '["Environ 48 %","Environ 52 %","Environ 56 %","Environ 60 %"]'::jsonb, 'C', 'En négligeant les pertes mécaniques et électriques : η_cc = η_TG + (1 − η_TG) × η_chaudière × η_vapeur = 0,38 + 0,62 × 0,85 × 0,35 ≈ 0,38 + 0,184 = 0,564, soit environ 56 %.', true),
  ('examen-12', 'examen', 12, 3, 'Pourquoi le rendement marginal de la post-combustion (duct burner) d’une chaudière de récupération est-il inférieur au rendement global du cycle combiné ?', '["Parce qu’elle augmente les pertes par rayonnement","Parce qu’elle élève la température d’entrée de la turbine à gaz","Parce qu’elle produit plus de NOx uniquement","Parce que la chaleur ajoutée n’est valorisée que par le cycle vapeur, dont le rendement est inférieur à celui du cycle combiné"]'::jsonb, 'D', 'La chaleur apportée par la post-combustion n’est convertie que par le cycle vapeur (rendement d’environ 35 à 40 %), alors que le gaz brûlé dans la turbine bénéficie des deux cycles. La post-combustion apporte de la puissance de pointe et de la souplesse, au prix d’un rendement marginal plus faible.', false),
  ('examen-13', 'examen', 13, 3, 'Dans le suivi de la performance énergétique (ISO 50001), que représente la courbe CUSUM ?', '["La somme cumulée des écarts entre consommation réelle et consommation prévue par le modèle de référence, dont la pente révèle les dérives et les économies","La moyenne des consommations sur douze mois","Le maximum de consommation observé en un mois","Le ratio entre l’énergie consommée et le prix du combustible"]'::jsonb, 'A', 'Le CUSUM trace la somme cumulée des écarts entre consommation réelle et consommation attendue (modèle de référence, par exemple une régression sur la charge et la température). Une pente descendante révèle des économies, une pente montante une dérive. Il rend visibles des dérives faibles que la lecture mensuelle masque.', false),
  ('examen-14', 'examen', 14, 4, 'Les émissions de NOx d’une turbine à gaz sont mesurées à 25 ppm avec 14 % d’O₂ (sec). Quelle est la concentration corrigée à la référence de 15 % d’O₂ ?', '["18,5 ppm","21,4 ppm","25,0 ppm","29,2 ppm"]'::jsonb, 'B', 'C_corrigé = C_mesuré × (20,9 − 15) / (20,9 − O₂ mesuré) = 25 × 5,9 / 6,9 ≈ 21,4 ppm. Quand l’O₂ mesuré est inférieur à 15 %, les fumées sont moins diluées que la référence : la concentration corrigée est donc plus basse.', true),
  ('examen-15', 'examen', 15, 4, 'Pourquoi une chaudière de récupération moderne comporte-t-elle plusieurs niveaux de pression (HP/MP/BP) plutôt qu’un seul ?', '["Pour augmenter la pression de la vapeur à l’échappement","Pour réduire le nombre d’équipements","Pour mieux épouser la courbe de refroidissement des gaz, réduire les irréversibilités et abaisser la température des fumées en cheminée","Pour supprimer le besoin de dégazeur"]'::jsonb, 'C', 'Les gaz se refroidissent de manière quasi continue de 600 °C à moins de 100 °C, alors que l’eau change d’état à température constante. Plusieurs niveaux de pression permettent de mieux ajuster les deux courbes, donc de réduire les écarts de température (irréversibilités) et de descendre la température en cheminée, au prix d’un coût d’investissement plus élevé.', false)
